import React from 'react';
import { motion } from 'framer-motion';

const AnimatedText = ({ text, el: Wrapper = 'p', className, delay = 0 }) => {
  const textArray = Array.isArray(text) ? text : [text];
  
  return (
    <Wrapper className={className}>
      {textArray.map((line, lineIndex) => (
        <span key={lineIndex} style={{ display: 'block', overflow: 'hidden', paddingBottom: '0.15em', paddingTop: '0.15em', marginTop: '-0.15em', marginBottom: '-0.15em' }}>
          <motion.span
            initial={{ y: '100%' }}
            whileInView={{ y: 0 }}
            viewport={{ once: true, margin: '-50px' }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1], delay: delay + (lineIndex * 0.1) }}
            style={{ display: 'block' }}
          >
            {line}
          </motion.span>
        </span>
      ))}
    </Wrapper>
  );
};

export default AnimatedText;
